using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> Authorize(
        HttpStatusCode status, string? body, Money? amount = null)
    {
        var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", amount ?? new Money(12.50m, "eur"), CancellationToken.None);
        await provider.Received;
        return (outcome, provider);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        var (_, provider) = await Authorize(HttpStatusCode.OK, """{"status":"approved"}""");
        using var _ = provider;

        Assert.Equal("POST", provider.Method);
        Assert.Equal("/v1/authorizations", provider.Path);
        Assert.StartsWith("application/json", provider.RequestContentType);

        using var json = JsonDocument.Parse(provider.RequestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.OK, """{"status":"approved"}""");
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.OK, """{"status":"declined"}""");
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.OK, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline()
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.PaymentRequired, """{"error":"insufficient_funds"}""");
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_and_no_body_is_a_decline()
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.PaymentRequired, null);
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"outcome":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_say_approved_is_never_treated_as_approved(string body)
    {
        var (outcome, provider) = await Authorize(HttpStatusCode.OK, body);
        using var _ = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(HttpStatusCode status)
    {
        using var provider = new FakeProvider(status, """{"status":"approved"}""");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(5, "USD"), CancellationToken.None));
    }

    [Fact]
    public async Task A_success_answer_that_is_not_json_surfaces_as_an_error()
    {
        using var provider = new FakeProvider(HttpStatusCode.OK, "<html>oops</html>", "text/html");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };

        await Assert.ThrowsAnyAsync<Exception>(() =>
            new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(5, "USD"), CancellationToken.None));
    }
}
